    o: [{ en: "30 to 50 km/h", ar: "30 إلى 50 كم/س" }, { en: "70 to 90 km/h", ar: "70 إلى 90 كم/س" }, { en: "110 to 130 km/h", ar: "110 إلى 130 كم/س" }, { en: "Over 140 km/h", ar: "أكثر من 140 كم/س" }],
