    o: [{ en: "Speed up to stay ahead", ar: "تزيد سرعتك لتبقى أمامها" }, { en: "Stop immediately where you are", ar: "تتوقف فورا مكانك" }, { en: "Ignore it until it overtakes", ar: "تتجاهلها حتى تتجاوزك" }, { en: "Clear the lane and keep to the right side of the road", ar: "تخلي المسار وتلتزم بالجانب الأيمن من الطريق" }],
