    o: [{ en: "Open the window and carry on", ar: "تفتح النافذة وتتابع" }, { en: "Stop in a safe place and rest", ar: "تتوقف في مكان آمن وتستريح" }, { en: "Drive faster to arrive sooner", ar: "تسرع لتصل أسرع" }, { en: "Turn the music up", ar: "ترفع صوت الموسيقى" }],
